function saveBox(){const payload=boxPayload();box.exportStatus='';const exportButton=$('boxExportBtn');if(exportButton&&!exportButton.disabled){exportButton.textContent='导出Box';exportButton.title='';}clearTimeout(boxSaveTimer);if(!desktopMode){localStorage.setItem(BOX_KEY,JSON.stringify(payload));OLD_BOX_KEYS.forEach(k=>localStorage.removeItem(k));box.saveStatus='已保存到浏览器';}else{const revision=++boxSaveRevision;box.saveStatus='正在保存到本机';boxSaveTimer=setTimeout(()=>{boxSaveChain=boxSaveChain.then(()=>revision===boxSaveRevision?saveBoxToServer(payload,revision):undefined);},180);}if(state.page==='box'||state.page==='banner')requestAnimationFrame(()=>{if(state.page==='box')renderBox();else renderBanner();});}
function syncBoxFromServer(){return fetch('/api/zzz/box',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error(`Box 读取失败（${r.status}）`))).then(server=>{server.fromServer=true;applyBoxRaw(server);localStorage.setItem(BOX_KEY,JSON.stringify(server));OLD_BOX_KEYS.forEach(k=>localStorage.removeItem(k));box.saveStatus='本机自动保存';});}
