function slateTeamSlugs(item){return new Set(item.members.map(member=>member.slug))}
function compareSlateStates(a,b){return b.filled-a.filled||b.totalScore-a.totalScore||a.key.localeCompare(b.key)}
function recSlateCandidateLists(scopeList,limit){return scopeList.map((scope,index)=>{const reserved=new Set(scopeList.slice(index+1).flatMap(other=>[...constraintSets(rec.mode,other.key).required]));return rankedFor(rec.mode,scope.key,new Set(),{ignoreSearch:true,reserved}).slice(0,limit);});}
function searchRecSlate(candidateLists,beamWidth){let states=[{picks:[],used:new Set(),filled:0,totalScore:0,key:''}];candidateLists.forEach(candidates=>{const next=[];states.forEach(state=>{next.push({...state,picks:[...state.picks,null],key:`${state.key}|~`});candidates.forEach(item=>{const slugs=slateTeamSlugs(item);if([...slugs].some(slug=>state.used.has(slug)))return;next.push({picks:[...state.picks,item],used:new Set([...state.used,...slugs]),filled:state.filled+1,totalScore:state.totalScore+item.score,key:`${state.key}|${item.template.id||item.template.chars.join('+')}`});});});states=next.sort(compareSlateStates).slice(0,beamWidth);});return states.sort(compareSlateStates)[0]||{picks:candidateLists.map(()=>null),used:new Set(),filled:0,totalScore:0,key:''};}
function bestRecSlatePlan(scopeList){const fast=searchRecSlate(recSlateCandidateLists(scopeList,50),180);if(scopeList.length>2&&fast.filled===scopeList.length)return fast.picks;const fallback=searchRecSlate(recSlateCandidateLists(scopeList,240),720);return(compareSlateStates(fast,fallback)<=0?fast:fallback).picks;}
function renderRecSlate(){const list=$('recSlateList'),scopeList=recPlanScopes(),picks=bestRecSlatePlan(scopeList),chosen=scopeList.map((scope,index)=>({scope,item:picks[index]||null})),scoreMeta=recSortMeta();list.innerHTML='';$('recSlateSubtitle').textContent=`${chosen.filter(x=>x.item).length}/${scopeList.length} 队 · 目标：${scoreMeta.label} · 只优化已选关卡 · 遵守各关必上/排除 · 不复用代理人`;if(!chosen.length){list.innerHTML='<div class="empty">暂无已选参战关卡</div>';return;}chosen.forEach(({scope,item})=>{const card=document.createElement('div');card.className=`rec-slate-card ${item?.risks?.length&&rec.riskMode!=='off'?'risky':''}`;if(!item){card.innerHTML=`<h3>${esc(scope.label)}</h3><div class="rec-meta">没有同时满足缺口、角色约束与不复用要求的队伍</div>`;}else{card.innerHTML=`<h3>${esc(scope.label)} · ${esc(scoreMeta.scoreLabel)} ${Math.round(item.score)} · ${item.ownedCount}/3 · 录入 ${item.recordedCount}/${item.ownedCount}</h3><div class="rec-slate-team">${item.members.map(member=>`<img class="${member.owned?'':'missing'} ${member.risks.length&&rec.riskMode!=='off'?'risky':''}" src="${esc(member.info.icon_url)}" title="${esc(charName(member.slug))}" alt="">`).join('')}</div>${riskHtml(item)}`;}list.appendChild(card);});}
